import React from 'react';
import { useDraggable } from '@dnd-kit/core';
import PlayerCard from './PlayerCard';

const DraggablePlayerCard = ({ 
  id, 
  player, 
  isSelected = false, 
  isAvailable = true, 
  onClick,
  size = 'normal',
  onField = false
}) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    isDragging,
  } = useDraggable({
    id: id,
    data: {
      type: 'player',
      player: player,
    },
  });

  const style = transform ? {
    transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
    zIndex: isDragging ? 1000 : 'auto',
    opacity: isDragging ? 0.8 : 1,
  } : {};

  // When rendering on the pitch, render a minimal card to guarantee cleanliness
  if (onField) {
    const resolveImg = (src) => {
      if (!src) return process.env.PUBLIC_URL + '/images/players/default-player.png';
      if (/^https?:|^data:/.test(src)) return src;
      if (src.startsWith('/')) return (process.env.PUBLIC_URL || '') + src;
      return src;
    };
    return (
      <div
        ref={setNodeRef}
        style={style}
        {...listeners}
        {...attributes}
      >
        <div className={`player-card on-field ${isDragging ? 'dragging' : ''}`} onClick={onClick}>
          <img
            src={resolveImg(player?.image)}
            alt={player?.name || 'player'}
            className="field-player-pure-image"
            onError={(e) => {
              e.target.src = process.env.PUBLIC_URL + '/images/players/default-player.png';
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...listeners}
      {...attributes}
    >
      <PlayerCard
        player={player}
        isSelected={isSelected}
        isAvailable={isAvailable}
        onClick={onClick}
        size={size}
        isDragging={isDragging}
        onField={false}
      />
    </div>
  );
};

export default DraggablePlayerCard;